gingface_hub/inference/_client.py","what":"sync InferenceClient task methods"},{"path":"src/huggingface_hub/inference/_providers","what":"per-provider adapters"},{"path":"utils/generate_async_inference_client.py","what":"generator for the async client"}],"shaped_by":"The history list does not say.","basis":"564eb61495e8","head":"2c61ae8c11eedb1b79e262dd9eb5e68962cac063","generated_at":"2026-11-15T07:29:34+00:00"}},{"id":"inference/client","name":"InferenceClient","kind":"module","summary":"Task methods, request/response handling and streaming.","decision":"Sync client is authoritative; async generated from it.","alternatives":"Hand-maintained async.","why":"Avoids drift.","paths":["src/huggingface_hub/inference/_client.py","src/huggingface_hub/inference/_common.py","utils/generate_async_inference_client.py"],"centrality":5,"scope":"architectural","importance":0.297,"history":[],"parent":"inference","orientation":null},{"id":"inference/providers","name":"Provider adapters","kind":"boundary","summary":"Per-provider helpers that build URLs, payloads and parse responses.","decision":"One class per provider behind a registry.","alternatives":"Single generic mapping.","why":"Providers differ in payloads and auth.","paths":["src/huggingface_hub/inference/_providers"],"centrality":4,"scope":"architectural","importance":0.206,"history":[],"parent":"inference","orientation":null},{"id":"inference/types","name":"Generated task types","kind":"boundary","summary":"Dataclass types for each task's inputs/outputs generated from the JSON specs.","decision":"Generated dataclasses rather than hand-written ones.","alternatives":"pydantic models.","why":"Stay in sync with the hub-docs specs.","paths":["src/huggingface_hub/inference/_generated/types","utils/generate_inference_types.py"],"centrality":3,"scope":"architectural","importance":0.142,"history":[],"parent":"inference","orientation":null},{"id":"hf-filesystem-buckets","name":"HfFileSystem, buckets and hot reload","kind":"module","summary":"fsspec filesystem over Hub repos and buckets, plus bucket live-follow and Spaces hot-reload.","decision":"fsspec-based POSIX-like access, with Buckets as a separate storage type using Xet.","alternatives":"Only download/upload helpers; custom file API.","why":"Interop with pandas/datasets via fsspec; buckets API was added AI-assisted.","paths":["src/huggingface_hub/hf_file_system.py","src/huggingface_hub/_buckets.py","src/huggingface_hub/_bucket_live_follow.py","src/huggingface_hub/_hot_reload"],"centrality":3,"scope":"architectural","importance":0.413,"history":[{"sha":"c837937","date":"2026-02-19","klass":"human","agent":null,"author":"Charles","subject":"feat(spaces): hot-reload (#3776)"},{"sha":"eaac6fe","date":"2026-02-24","klass":"assisted","agent":"cursor","author":"Lucain","subject":"Buckets API (#3673)"}],"parent":null,"orientation":{"purpose":"Gives Hub repos and buckets a file-system interface (fsspec) that tools like pandas and datasets can use. It also holds bucket live-following and Spaces hot-reload.","decision":"A POSIX-like fsspec filesystem, with Buckets as a separate Xet-backed storage type. Plain download and upload helpers or a custom file API were not chosen. fsspec gives interoperability with the data ecosystem.","where":[{"path":"src/huggingface_hub/hf_file_system.py","what":"HfFileSystem implementation"},{"path":"src/huggingface_hub/_buckets.py","what":"bucket types and operations"},{"path":"src/huggingface_hub/_hot_reload","what":"Spaces hot-reload code"}],"shaped_by":"Charles wrote hot-reload in Feb 2026 [human]; Lucain's Buckets API that month was [assisted] with Cursor.","basis":"5200ea6f4f32","head":"2c61ae8c11eedb1b79e262dd9eb5e68962cac063","generated_at":"2026-11-15T07:29:34+00:00"}},{"id":"repocard-mixin","name":"Repo cards and ModelHubMixin","kind":"module","summary":"Model/dataset card parsing and metadata plus the mixin that gives ML framework classes save/push/from_pretrained.","decision":"YAML front-matter cards with 